+fn recover_interrupted_operations<W: ReleaseStateWriter>(
+    capability: &ValidatedReleaseIntent<'_>,
+    store: &ReleaseStateStore<W>,
+    permit: &ApplyPermit,
+    state: &mut ReleaseExecutionStateV1,
+    artifacts: Option<&VerifiedArtifactManifest<'_>>,
