//! Fresh, graph-owned authorization for durable release intents.
//!
//! This module intentionally takes a root, locator, and runner rather than a
//! [`Workspace`]. A workspace caches parsed manifests and config for a normal
//! command invocation; accepting one here would make a previously observed
//! graph look current after the filesystem changed.

use std::collections::{BTreeMap, BTreeSet};
use std::path::Path;

use callisto_model::{
    ApplyPermit, ArtifactSlotId, CanonicalTranscript, CommandOutput, CommandRunner, CommitSha, DepKind, Ecosystem,
    ExecutionTrustProfileV1, GitHubRepository, GitHubRepositoryParseError, NpmAccess, OperationOutcome,
    ProviderObservationV1, PublishOutcome, PublishTarget, RegistryBindingDigest, RegistryBindingId, RegistryKey,
    ReleaseDecisionV1, ReleaseInputSnapshotV1, ReleaseIntentError, ReleaseIntentV1, ReleaseOperation,
    ReleaseOperationId, ReleaseOperationObservationV1, ReleasePackageId, ReleasePackageInputV1, ReleaseProfileId,
    SemanticInputDigest, SourceIdentity, TagName, Version,
};
use callisto_vcs::{
    access::{GitCommitTrustEvidence, GitHeadDisposition},
    release_lock::ReleaseWorkspaceLock,
    GitAccess, GitDataSource, TagSignPolicy,
};

use crate::config::ReleaseProfileConfig;
use crate::error::{
    CommandFailure, ReleasePreconditionRequirement, ReleaseSelectionInvalidReason, RemoteConflict,
    UnsupportedReleaseFeature,
};
use crate::{commands::registry_argv, DependencyResolver, GraphError, ProjectLocator, Workspace};

use super::release_artifacts::VerifiedArtifactManifest;

/// Reason carried by [`GraphError::ReleaseIntentStale`] (E124); real reasons are constructible only from this module.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct StaleReason {
    kind: StaleKind,
}

#[derive(Clone, Debug, PartialEq, Eq, thiserror::Error)]
enum StaleKind {
    #[error("the re-observed Git commit trust evidence no longer matches what the intent was validated against")]
    TrustEvidenceChanged,
    #[error("the re-observed source identity no longer matches what the intent was validated against")]
    SourceIdentityChanged,
    #[error("the re-observed Git push remote no longer matches what the intent was validated against")]
    GitRemoteChanged,
    #[error("a fresh derivation from the current workspace no longer matches the intent that was validated")]
    IntentDiffersFromFreshDerivation,
}

impl std::fmt::Display for StaleReason {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        std::fmt::Display::fmt(&self.kind, formatter)
    }
}

impl StaleReason {
    fn trust_evidence_changed() -> Self {
        StaleReason {
            kind: StaleKind::TrustEvidenceChanged,
        }
    }

    fn source_identity_changed() -> Self {
        StaleReason {
            kind: StaleKind::SourceIdentityChanged,
        }
    }

    fn git_remote_changed() -> Self {
        StaleReason {
            kind: StaleKind::GitRemoteChanged,
        }
    }

    fn intent_differs_from_fresh_derivation() -> Self {
        StaleReason {
            kind: StaleKind::IntentDiffersFromFreshDerivation,
        }
    }
}

/// The invocation data for one effect. This is deliberately graph-private:
/// callers can inspect the serializable intent, but cannot substitute a new
/// endpoint, tag target, or package directory at execution time.
#[allow(dead_code)] // consumed by the durable executor batch
#[derive(Debug)]
enum PreparedOperation {
    RegistryPublish {
        package_dir: std::path::PathBuf,
        package_name: String,
        version: Version,
        registry: PreparedRegistryBinding,
        npm_access: Option<NpmAccess>,
        npm_tag: Option<String>,
    },
    Tag {
        name: TagName,
        target: CommitSha,
        annotation: String,
    },
    ForgeRelease {
        tag: TagName,
    },
    ArtifactUpload {
        slot: ArtifactSlotId,
        tag: TagName,
    },
}

/// Coordinator-owned identity used to bind a product artifact to the exact
/// workflow revision that built it. This is distinct from a historic release
/// source during recovery.
#[derive(Clone, Debug)]
pub struct ArtifactBuildPolicy {
    pub repository: GitHubRepository,
    pub workflow_path: String,
    pub workflow_commit: CommitSha,
}

/// Credential-free, canonical registry routing. `endpoint` is populated only
/// after parsing rejects userinfo, query, and fragments, so a later executor
/// cannot recover credentials from this capability.
#[allow(dead_code)] // consumed by the durable executor batch
#[derive(Debug)]
struct PreparedRegistryBinding {
    key: RegistryKey,
    endpoint: Option<String>,
    identity: RegistryBindingDigest,
}

/// Immutable, credential-free destination for Git effects. Its canonical
/// digest is included in each tag-producing package fingerprint; the URL is
/// retained only in the validated, non-serializable capability.
#[derive(Clone, Debug, PartialEq, Eq)]
struct PreparedGitRemote {
    endpoint: String,
    identity: SemanticInputDigest,
    github_repository: Option<GitHubRepository>,
}

/// Graph-private inputs prepared from the same fresh observation as an intent.
/// The executor will consume these when introduced; retaining them in the
/// capability prevents a validated public intent being paired with new inputs.
#[allow(dead_code)] // consumed by the durable executor batch
#[derive(Debug)]
struct PreparedReleaseInputs {
    root: std::path::PathBuf,
    source: SourceIdentity,
    trust: GitCommitTrustEvidence,
    git_remote: Option<PreparedGitRemote>,
    _lock: ReleaseWorkspaceLock,
    operations: BTreeMap<ReleaseOperationId, PreparedOperation>,
}

#[derive(Debug, PartialEq, Eq)]
struct ObservedTag {
    target: CommitSha,
    annotation: String,
}

#[derive(Debug, PartialEq, Eq)]
enum ForgeReleaseObservation {
    Missing,
    Exact,
    Conflict,
    Indeterminate,
}

type DerivedReleaseInputs = (
    ReleaseInputSnapshotV1,
    Vec<ReleaseOperation>,
    BTreeMap<ReleaseOperationId, PreparedOperation>,
    Option<PreparedGitRemote>,
    Vec<ArtifactSlotId>,
);

struct PreparedDerivation {
    operations: BTreeMap<ReleaseOperationId, PreparedOperation>,
    git_remote: Option<PreparedGitRemote>,
}

/// In-memory, non-transferable proof that an intent was rebuilt from a fresh
/// workspace observation. It is intentionally neither cloneable nor serializable.
pub struct ValidatedReleaseIntent<'a> {
    intent: ReleaseIntentV1,
    prepared: PreparedReleaseInputs,
    #[allow(dead_code)] // consumed by the durable execution coordinator
    runner: &'a dyn CommandRunner,
}

impl std::fmt::Debug for ValidatedReleaseIntent<'_> {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter
            .debug_struct("ValidatedReleaseIntent")
            .field("intent", &self.intent)
            .finish_non_exhaustive()
    }
}

impl ValidatedReleaseIntent<'_> {
    pub fn intent(&self) -> &ReleaseIntentV1 {
        &self.intent
    }

    #[allow(dead_code)] // consumed by the durable executor batch
    fn prepared(&self) -> &PreparedReleaseInputs {
        &self.prepared
    }

    /// Re-observes the held workspace immediately before an effect.
    #[allow(dead_code)] // consumed by the durable execution coordinator
    pub(crate) fn recheck_trust(&self) -> Result<(), GraphError> {
        let evidence =
            callisto_vcs::GitAccess::discover(&self.prepared.root, self.runner).observe_git_commit_trust()?;
        if evidence != self.prepared.trust || source_from_trust(&evidence) != self.prepared.source {
            return Err(GraphError::ReleaseIntentStale {
                reason: StaleReason::trust_evidence_changed(),
            });
        }
        if self
            .prepared
            .git_remote
            .as_ref()
            .is_some_and(|expected| prepared_git_remote(&self.prepared.root, self.runner).as_ref() != Ok(expected))
        {
            return Err(GraphError::ReleaseIntentStale {
                reason: StaleReason::git_remote_changed(),
            });
        }
        Ok(())
    }
}

/// Collects one fresh, exact-provider observation for every operation in the
/// immutable intent.
///
/// A terminal receipt is deliberately built from this result rather than from
/// local execution state. The caller must reject any non-exact result; this
/// function preserves the complete roster so receipt construction can prove
/// that it did not silently omit an operation.
pub fn observe_release_operations(
    capability: &ValidatedReleaseIntent<'_>,
) -> Result<Vec<ReleaseOperationObservationV1>, GraphError> {
    observe_release_operations_with_artifacts(capability, None)
}

/// Collects provider observations using verified artifact bytes when the
/// intent declares binary uploads. The verified capability prevents recovery
/// from accepting a same-named remote asset with different bytes.
pub fn observe_release_operations_with_artifacts(
    capability: &ValidatedReleaseIntent<'_>,
    artifacts: Option<&VerifiedArtifactManifest<'_>>,
) -> Result<Vec<ReleaseOperationObservationV1>, GraphError> {
    capability
        .intent()
        .operations
        .iter()
        .map(|operation| {
            capability.recheck_trust()?;
            Ok(ReleaseOperationObservationV1 {
                operation: operation.id().clone(),
                observation: capability.observe_prepared(operation.id(), artifacts)?,
            })
        })
        .collect()
}

/// Builds a release intent from a fresh root-bound observation.
pub fn build_release_intent<L: ProjectLocator, R: CommandRunner>(
    root: &Path,
    locator: &L,
    runner: &R,
    decision: &ReleaseDecisionV1,
    profile: ReleaseProfileId,
    trust_profile: ExecutionTrustProfileV1,
) -> Result<ReleaseIntentV1, GraphError> {
    let root = canonical_root(root)?;
    let workspace = Workspace::load(root.clone(), locator, runner)?;
    let source = observe_source(&workspace, trust_profile)?;
    let intent = derive_release_intent(&workspace, decision, profile, source.clone(), trust_profile, None)?;

    // Recheck after all input reads. A concurrent edit or checkout cannot be
    // authorized merely because it happened after the first check.
    if observe_source(&workspace, trust_profile)? != source {
        return Err(GraphError::ReleaseIntentStale {
            reason: StaleReason::source_identity_changed(),
        });
    }
    Ok(intent)
}

/// Builds an intent whose declared binary slots are bound to the current
/// coordinator workflow. Callers recovering an old release source must pass
/// the current coordinator revision here, never substitute the source SHA.
pub fn build_release_intent_with_artifacts<L: ProjectLocator, R: CommandRunner>(
    root: &Path,
    locator: &L,
    runner: &R,
    decision: &ReleaseDecisionV1,
    profile: ReleaseProfileId,
    trust_profile: ExecutionTrustProfileV1,
    artifact_policy: ArtifactBuildPolicy,
) -> Result<ReleaseIntentV1, GraphError> {
    let root = canonical_root(root)?;
    let workspace = Workspace::load(root.clone(), locator, runner)?;
    let source = observe_source(&workspace, trust_profile)?;
    let intent = derive_release_intent(
        &workspace,
        decision,
        profile,
        source.clone(),
        trust_profile,
        Some(&artifact_policy),
    )?;
    if observe_source(&workspace, trust_profile)? != source {
        return Err(GraphError::ReleaseIntentStale {
            reason: StaleReason::source_identity_changed(),
        });
    }
    Ok(intent)
}

/// Re-observes root, config, package discovery, manifests, Git evidence, and
/// the exact operation DAG before creating an opaque authorization capability.
pub fn validate_release_intent<'a, L: ProjectLocator, R: CommandRunner>(
    root: &Path,
    locator: &L,
    runner: &'a R,
    received: ReleaseIntentV1,
) -> Result<ValidatedReleaseIntent<'a>, GraphError> {
    validate_release_intent_with_state_directory(root, locator, runner, None, received)
}

/// Validates an intent while placing its workspace lock under an explicit
/// caller-owned state directory.
///
/// CI callers that supply an explicit durable state file must use its parent
/// here as well.  Otherwise validation would still depend on the runner's
/// implicit platform state location, defeating hermetic job handoff.
pub fn validate_release_intent_with_state_directory<'a, L: ProjectLocator, R: CommandRunner>(
    root: &Path,
    locator: &L,
    runner: &'a R,
    state_directory: Option<&Path>,
    received: ReleaseIntentV1,
) -> Result<ValidatedReleaseIntent<'a>, GraphError> {
    let root = canonical_root(root)?;
    let workspace = Workspace::load(root.clone(), locator, runner)?;
    let initial_trust = observe_git_trust(&workspace, received.trust_profile)?;
    let lock = ReleaseWorkspaceLock::acquire(&root, state_directory)?;
    let trust = observe_git_trust(&workspace, received.trust_profile)?;
    if trust != initial_trust {
        return Err(GraphError::ReleaseIntentStale {
            reason: StaleReason::trust_evidence_changed(),
        });
    }
    let source = source_from_trust(&trust);
    let artifact_policy = artifact_policy_from_intent(&received)?;
    let (expected, prepared) = derive_release_intent_with_prepared(
        &workspace,
        &received.decision,
        received.profile.clone(),
        source.clone(),
        received.trust_profile,
        artifact_policy.as_ref(),
    )?;
    let final_trust = observe_git_trust(&workspace, received.trust_profile)?;
    if expected != received || final_trust != trust {
        return Err(GraphError::ReleaseIntentStale {
            reason: StaleReason::intent_differs_from_fresh_derivation(),
        });
    }

    Ok(ValidatedReleaseIntent {
        prepared: PreparedReleaseInputs {
            root,
            source,
            trust: final_trust,
            git_remote: prepared.git_remote,
            _lock: lock,
            operations: prepared.operations,
        },
        intent: received,
        runner,
    })
}

fn canonical_root(root: &Path) -> Result<std::path::PathBuf, GraphError> {
    dunce::canonicalize(root).map_err(|error| GraphError::ReleaseInputRead {
        path: root.to_path_buf(),
        message: error.to_string(),
    })
}

fn observe_source<R: CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    trust_profile: ExecutionTrustProfileV1,
) -> Result<SourceIdentity, GraphError> {
    Ok(source_from_trust(&observe_git_trust(workspace, trust_profile)?))
}

fn observe_git_trust<R: CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    trust_profile: ExecutionTrustProfileV1,
) -> Result<GitCommitTrustEvidence, GraphError> {
    if !matches!(trust_profile, ExecutionTrustProfileV1::GitCommit) {
        return Err(ReleaseIntentError::UnsupportedTrustProfile.into());
    }
    let evidence = workspace.git_access().observe_git_commit_trust()?;
    if evidence.canonical_root() != workspace.root {
        return Err(GraphError::ReleasePreconditionUnmet {
            requirement: ReleasePreconditionRequirement::CanonicalRootMatchesWorkspace,
        });
    }
    if evidence.head_disposition() != GitHeadDisposition::Detached {
        return Err(GraphError::ReleasePreconditionUnmet {
            requirement: ReleasePreconditionRequirement::DetachedHead,
        });
    }
    Ok(evidence)
}

fn source_from_trust(evidence: &GitCommitTrustEvidence) -> SourceIdentity {
    SourceIdentity::GitCommit {
        sha: evidence.head().clone(),
    }
}

impl ValidatedReleaseIntent<'_> {
    /// Dispatches exactly one graph-private operation prepared during fresh
    /// validation. This is intentionally the only production effect path: it
    /// never accepts a path, endpoint, tag, package name, or version from a
    /// caller.
    pub(crate) fn dispatch_prepared(
        &self,
        permit: &ApplyPermit,
        id: &ReleaseOperationId,
        artifacts: Option<&VerifiedArtifactManifest<'_>>,
    ) -> Result<OperationOutcome, GraphError> {
        let operation = self
            .prepared
            .operations
            .get(id)
            .ok_or_else(|| GraphError::ReleaseInvariant {
                detail: format!("dispatch_prepared: no prepared operation for `{id:?}`"),
            })?;
        match operation {
            PreparedOperation::RegistryPublish { .. } => self.dispatch_registry(permit, id, operation),
            PreparedOperation::Tag {
                name,
                target,
                annotation,
            } => self.dispatch_tag(permit, name, target, annotation),
            PreparedOperation::ForgeRelease { tag } => self.dispatch_forge_release(id, tag),
            PreparedOperation::ArtifactUpload { slot, tag } => self.dispatch_artifact_upload(id, slot, tag, artifacts),
        }
    }

    /// Observes the exact provider identity prepared with this capability.
    ///
    /// This path accepts no caller-controlled endpoint, package, tag, or
    /// release name. It is therefore safe to use when a local state file says
    /// an effect was interrupted: remote state decides whether execution may
    /// converge, never a stale runner-local journal.
    pub(crate) fn observe_prepared(
        &self,
        id: &ReleaseOperationId,
        artifacts: Option<&VerifiedArtifactManifest<'_>>,
    ) -> Result<ProviderObservationV1, GraphError> {
        let operation = self
            .prepared
            .operations
            .get(id)
            .ok_or_else(|| GraphError::ReleaseInvariant {
                detail: format!("observe_prepared: no prepared operation for `{id:?}`"),
            })?;
        match operation {
            PreparedOperation::RegistryPublish {
                package_name,
                version,
                registry,
                ..
            } => match id.package.ecosystem() {
                Ecosystem::Cargo => {
                    let registry_key = (registry.key.as_str() != RegistryKey::CRATES_IO).then(|| registry.key.as_str());
                    Ok(
                        if self.cargo_version_is_published(package_name, version, registry_key)? {
                            ProviderObservationV1::Exact
                        } else {
                            ProviderObservationV1::Absent
                        },
                    )
                }
                Ecosystem::Npm => Ok(
                    if self.npm_version_is_published(package_name, version, registry.endpoint.as_deref())? {
                        ProviderObservationV1::Exact
                    } else {
                        ProviderObservationV1::Absent
                    },
                ),
                // PyPI's upload endpoint is not a query API. Until its
                // provider adapter can prove an exact version through the
                // configured index, recovery must fail closed rather than
                // attempting a second upload.
                Ecosystem::Pypi => Ok(ProviderObservationV1::Indeterminate),
                _ => Err(GraphError::UnsupportedRelease {
                    feature: UnsupportedReleaseFeature::Ecosystem,
                }),
            },
            PreparedOperation::Tag {
                name,
                target,
                annotation,
            } => Ok(match self.observed_tag(name)? {
                None => ProviderObservationV1::Absent,
                Some(observed) if observed.target == *target && observed.annotation == *annotation => {
                    ProviderObservationV1::Exact
                }

