                            workspace.root.display()
                        ))
                    })?
                    .to_path_buf()
            } else {
                decision_path.to_path_buf()
            };
            let decision_path = callisto_model::workspace_relative(&decision_path).map_err(|error| {
                CliError::Other(format!(
                    "invalid release decision path {}: {error}",
                    decision_path.display()
                ))
            })?;
            derive_release_commit_decision(&workspace, &commit, &decision_path)?
        }
        None => {
            let selections = args
                .packages
                .iter()
                .map(|raw| {
                    ReleasePackageId::parse(raw).map_err(|error| {
                        CliError::Other(format!(
                            "invalid release package `{raw}`: {error}; use an exact ecosystem-qualified identity such as cargo/callisto-cli"
                        ))
                    })
                })
                .collect::<Result<Vec<_>, _>>()?;
            let inference = select_inference();
            let version_plan =
                callisto_graph::commands::plan_version(&workspace, &inference, &VersionOptions::default())?;
            derive_selected_release_decision(&workspace, &version_plan, &selections)?
        }
    };
    let locator = IgnoreWalkLocator::new(&workspace.root);
    let intent = match (
        &workspace.config.product_release,
        &args.orchestration_revision,
        &args.artifact_repository,
    ) {
        (Some(_), Some(revision), Some(repository)) => {
            let workflow_commit = callisto_model::CommitSha::parse(revision)
                .map_err(|error| CliError::Other(format!("invalid orchestration revision `{revision}`: {error}")))?;
            let repository = callisto_model::GitHubRepository::parse(repository)
                .map_err(|error| CliError::Other(format!("invalid artifact repository `{repository}`: {error}")))?;
            let configured_profile = workspace
                .config
                .product_release
                .as_ref()
                .and_then(|release| release.profile(&profile))
                .ok_or_else(|| {
                    CliError::Other(format!(
                        "release profile `{}` is not configured with a forge destination",
                        profile.as_str()
                    ))
                })?;
            if configured_profile.forge_repository != repository {
                return Err(CliError::Other(format!(
                    "release profile `{}` targets forge repository `{}`, not `{}`",
                    profile.as_str(),
                    configured_profile.forge_repository.as_slug(),
                    repository.as_slug()
                )));
            }
            build_release_intent_with_artifacts(
                &workspace.root,
                &locator,
                &runner,
                &decision,
                profile.clone(),
                ExecutionTrustProfileV1::GitCommit,
                callisto_graph::commands::ArtifactBuildPolicy {
                    repository,
                    workflow_path: ".github/workflows/callisto-release.yml".to_owned(),
                    workflow_commit,
                },
            )?
        }
        (Some(_), _, _) => {
            return Err(CliError::Other(
                "product release planning requires --orchestration-revision and --artifact-repository".to_owned(),
            ));
        }
        (None, None, None) => build_release_intent(
            &workspace.root,
            &locator,
            &runner,
            &decision,
            profile,
            ExecutionTrustProfileV1::GitCommit,
        )?,
        (None, _, _) => {
            return Err(CliError::Other(
                "--orchestration-revision and --artifact-repository require a configured product release".to_owned(),
            ));
        }
    };
    let permit = ApplyPermit::granted_unless_dry_run(global.dry_run)
        .expect("release plan rejects --dry-run before creating its explicit output");
    write_intent(&args.out, &intent, &permit)?;
    match global.format {
        OutputFormat::Json => write_json(&mut std::io::stdout(), &intent)?,
        OutputFormat::Text => println!("Wrote release intent {} to {}", intent.digest(), args.out.display()),
    }
    Ok(ExitCode::SUCCESS)
}

fn inspect(args: ReleaseInspectArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
    let value = read_json_file(&args.input)?;
    match global.format {
        OutputFormat::Json => write_json(&mut std::io::stdout(), &value)?,
        OutputFormat::Text => println!(
            "{}",
            serde_json::to_string_pretty(&value).expect("JSON value serializes")
        ),
    }
    Ok(ExitCode::SUCCESS)
}

fn reconcile(args: ReleaseReconcileArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
    let intent = read_intent(&args.intent)?;
    let state = match args.state {
        Some(path) => ReleaseStateStore::new(path).load(&intent)?,
        None => None,
    }
    .unwrap_or_else(|| ReleaseExecutionStateV1::pending(&intent));
    let report = reconcile_release_execution(&intent, &state)?;
    match global.format {
        OutputFormat::Json => write_json(&mut std::io::stdout(), report.eligible())?,
        OutputFormat::Text => {
            for operation in report.eligible() {
                println!("eligible: {operation:?}");
            }
        }
    }
    Ok(ExitCode::SUCCESS)
}

fn execute(args: ReleaseExecuteArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
    let intent = read_intent(&args.intent)?;
    let selected_profile = ReleaseProfileId::parse(&args.profile)
        .map_err(|error| CliError::Other(format!("invalid release profile `{}`: {error}", args.profile)))?;
    if selected_profile != intent.profile {
        return Err(CliError::Other(format!(
            "release execute profile `{}` does not match immutable intent profile `{}`",
            selected_profile.as_str(),
            intent.profile.as_str()
        )));
    }
    let manifest = args
        .artifact_manifest
        .as_deref()
        .map(read_artifact_manifest)
        .transpose()?;
    let verified_artifacts = match (
        intent.artifact_slots.is_empty(),
        manifest.as_ref(),
        args.artifact_dir.as_deref(),
    ) {
        (true, None, None) => None,
        (true, _, _) => {
            return Err(CliError::Other(
                "release intent declares no binary artifact slots; omit --artifact-manifest and --artifact-dir"
                    .to_owned(),
            ));
        }
        (false, Some(manifest), Some(directory)) => {
            let runner = CliCommandRunner;
            Some(verify_artifact_manifest(&intent, manifest, directory, &runner)?)
        }
        (false, _, _) => {
            return Err(CliError::Other(
                "release intent declares binary artifact slots; provide both --artifact-manifest and --artifact-dir"
                    .to_owned(),
            ));
        }
    };
    let runner = CliCommandRunner;
    let source_global = source_global(global, args.source_root.as_deref());
    let source_workspace = load_workspace(&source_global, &runner)?;
    if source_workspace.config.product_release.is_some() {
        let configured_profile = source_workspace
            .config
            .product_release
            .as_ref()
            .and_then(|release| release.profile(&selected_profile))
            .ok_or_else(|| {
                CliError::Other(format!(
                    "release profile `{}` is not configured with a forge destination",
                    selected_profile.as_str()
                ))

    runs-on: ubuntu-latest
    permissions:
      contents: read
    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with:
          # The coordinator must be the current workflow revision. Recovery
          # never rebuilds its release engine from historic source.
          ref: ${{ needs.release-candidate.outputs.orchestration_sha }}
          fetch-depth: 0
          persist-credentials: false
      - uses: $/.github/actions/setup-callisto
        with:
          source: local
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with:
          ref: ${{ needs.release-candidate.outputs.release_source_sha }}
          path: release-source
          fetch-depth: 0
          persist-credentials: false
      - name: Derive and hash intent
        env:
          RELEASE_SOURCE_SHA: ${{ needs.release-candidate.outputs.release_source_sha }}
          ORCHESTRATION_SHA: ${{ needs.release-candidate.outputs.orchestration_sha }}
        run: |
          set -euo pipefail
          handoff_dir="${RUNNER_TEMP}/release-intent"
          mkdir -p "$handoff_dir"
          callisto release plan --profile production --source-root "$GITHUB_WORKSPACE/release-source" \
            --orchestration-revision "$ORCHESTRATION_SHA" --artifact-repository "$GITHUB_REPOSITORY" \
            --from-release-commit "$RELEASE_SOURCE_SHA" \
            --decision "$GITHUB_WORKSPACE/release-source/.callisto/release-decision.json" \
            --out "$handoff_dir/release-intent.json"
          shasum -a 256 "$handoff_dir/release-intent.json" > "$handoff_dir/release-intent.json.sha256"
      - uses: actions/upload-artifact@043fb46d1a93c77aae656e7c1c64a875d1fc6a0a # v7.0.1
        with:
          name: release-intent
          path: ${{ runner.temp }}/release-intent
          if-no-files-found: error
          retention-days: 1

  build-artifact:
    name: Build ${{ matrix.target }} from the intent-bound source tree
    needs: [plan, release-candidate]
    strategy:
      fail-fast: false
      matrix:
        include:
          - id: macos-arm64
            runner: macos-14
            target: aarch64-apple-darwin
            asset: callisto-aarch64-apple-darwin.tar.gz
            kind: cli
          - id: linux-gnu
            runner: ubuntu-latest
            target: x86_64-unknown-linux-gnu
            asset: callisto-x86_64-unknown-linux-gnu.tar.gz
            kind: cli
          - id: linux-musl
            runner: ubuntu-latest
            target: x86_64-unknown-linux-musl
            asset: callisto-x86_64-unknown-linux-musl.tar.gz
            kind: cross
          - id: wasm-wasi
            runner: ubuntu-latest
            target: wasm32-wasip1
            asset: callisto-moon.wasm
            kind: wasm
    runs-on: ${{ matrix.runner }}
    permissions:
      contents: read
      attestations: write
      id-token: write
    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with:
          ref: ${{ needs.release-candidate.outputs.orchestration_sha }}
          fetch-depth: 0
          persist-credentials: false
      - uses: $/.github/actions/setup-callisto
        with:
          source: local
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with:
          ref: ${{ needs.release-candidate.outputs.release_source_sha }}
          path: release-source
          fetch-depth: 0
          persist-credentials: false
      - uses: extractions/setup-just@53165ef7e734c5c07cb06b3c8e7b647c5aa16db3 # v4.0.0
        with:
          just-version: '1.58.0'
      - uses: actions/download-artifact@3e5f45b2cfb9172054b4087a40e8e0b5a5461e7c # v8.0.1
        with:
          name: release-intent
          path: ${{ runner.temp }}/release-intent
      - name: Verify handoff
        run: |
          set -euo pipefail
          handoff_dir="${RUNNER_TEMP}/release-intent"
          (cd "$handoff_dir" && shasum -a 256 -c release-intent.json.sha256)
          callisto release inspect --input "$handoff_dir/release-intent.json"
          mkdir -p "${RUNNER_TEMP}/release-artifacts"
      - name: Build declared artifact
        env:
          CALLISTO_RELEASE_ARTIFACT_KIND: ${{ matrix.kind }}
          CALLISTO_RELEASE_ARTIFACT_TARGET: ${{ matrix.target }}
          CALLISTO_RELEASE_ARTIFACT_ASSET: ${{ matrix.asset }}
          CALLISTO_RELEASE_SOURCE_ROOT: ${{ github.workspace }}/release-source
          CALLISTO_RELEASE_ARTIFACT_DIR: ${{ runner.temp }}/release-artifacts
        run: |
          bash .github/scripts/build-release-artifact.sh
      - name: Attest exact artifact bytes
        uses: actions/attest-build-provenance@4d101475d8b20a2381f78447822ac1eab6504dd8 # v4.2.2
        with:
          subject-path: ${{ runner.temp }}/release-artifacts/${{ matrix.asset }}
      - uses: actions/upload-artifact@043fb46d1a93c77aae656e7c1c64a875d1fc6a0a # v7.0.1
        with:
          name: release-build-${{ matrix.id }}
          path: ${{ runner.temp }}/release-artifacts/${{ matrix.asset }}
          if-no-files-found: error
          retention-days: 1

  build:
    name: Assemble attested product artifacts
    needs: [build-artifact, release-candidate]
    outputs:
      orchestration_sha: ${{ needs.release-candidate.outputs.orchestration_sha }}
      release_source_sha: ${{ needs.release-candidate.outputs.release_source_sha }}
    runs-on: ubuntu-latest
    permissions:
      contents: read
    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with:
          ref: ${{ needs.release-candidate.outputs.orchestration_sha }}
          fetch-depth: 0
          persist-credentials: false
      - uses: $/.github/actions/setup-callisto
        with:
          source: local
      - uses: actions/download-artifact@3e5f45b2cfb9172054b4087a40e8e0b5a5461e7c # v8.0.1
        with:
          name: release-intent
          path: ${{ runner.temp }}/release-intent
      - uses: actions/download-artifact@3e5f45b2cfb9172054b4087a40e8e0b5a5461e7c # v8.0.1
        with:
          name: release-build-macos-arm64
          path: ${{ runner.temp }}/release-artifacts
      - uses: actions/download-artifact@3e5f45b2cfb9172054b4087a40e8e0b5a5461e7c # v8.0.1
        with:
          name: release-build-linux-gnu
          path: ${{ runner.temp }}/release-artifacts
      - uses: actions/download-artifact@3e5f45b2cfb9172054b4087a40e8e0b5a5461e7c # v8.0.1
        with:
          name: release-build-linux-musl
          path: ${{ runner.temp }}/release-artifacts
      - uses: actions/download-artifact@3e5f45b2cfb9172054b4087a40e8e0b5a5461e7c # v8.0.1
        with:
          name: release-build-wasm-wasi
          path: ${{ runner.temp }}/release-artifacts
      - name: Create exact artifact manifest
        run: |
          set -euo pipefail
          callisto release artifact-manifest --intent "${RUNNER_TEMP}/release-intent/release-intent.json" --artifact-dir "${RUNNER_TEMP}/release-artifacts" --out "${RUNNER_TEMP}/release-artifacts/manifest.json"
      - uses: actions/upload-artifact@043fb46d1a93c77aae656e7c1c64a875d1fc6a0a # v7.0.1
        with:
          name: release-build
          path: |
            ${{ runner.temp }}/release-intent
            ${{ runner.temp }}/release-artifacts
          if-no-files-found: error
          retention-days: 1

  execute:
    name: Execute approved release
    needs: build
    runs-on: ubuntu-latest
    permissions:
      contents: write
      attestations: read
      id-token: write
    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with:
          ref: ${{ needs.build.outputs.orchestration_sha }}
          fetch-depth: 0
          persist-credentials: false
      - uses: $/.github/actions/setup-callisto
        with:
          source: local
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with:
          ref: ${{ needs.build.outputs.release_source_sha }}
          path: release-source
          fetch-depth: 0
          # The release-source checkout alone needs Git credentials because
          # graph-owned tag dispatch pushes from this repository.
          persist-credentials: true
      # Downloaded outside the workspace (under $RUNNER_TEMP, like
      # setup-callisto's own binary install): callisto release execute
      # re-checks release trust before every dispatch, which requires a
      # worktree with no tracked or untracked files -- landing these inside
      # the checkout would dirty it and fail that check before anything
      # gets published.
      - uses: actions/download-artifact@3e5f45b2cfb9172054b4087a40e8e0b5a5461e7c # v8.0.1
        with:
          name: release-intent
          path: ${{ runner.temp }}/release-intent
      - uses: actions/download-artifact@3e5f45b2cfb9172054b4087a40e8e0b5a5461e7c # v8.0.1
        with:
          name: release-build
          path: ${{ runner.temp }}/release-build
      - name: Verify same-run handoff before credentials
        run: |
          set -euo pipefail
          intent_dir="${RUNNER_TEMP}/release-intent"
          build_dir="${RUNNER_TEMP}/release-build"
          (cd "$intent_dir" && shasum -a 256 -c release-intent.json.sha256)
          cmp "$intent_dir/release-intent.json" "$build_dir/release-intent/release-intent.json"
      - name: Execute verified release
        env:
          CARGO_REGISTRY_TOKEN: ${{ secrets.CARGO_REGISTRY_TOKEN }}
          NPM_TOKEN: ${{ secrets.NPM_TOKEN }}
          TWINE_PASSWORD: ${{ secrets.TWINE_PASSWORD }}
          GH_TOKEN: ${{ github.token }}
          RELEASE_SOURCE_SHA_INPUT: ${{ inputs.release_source_sha }}
          ORCHESTRATION_SHA: ${{ needs.build.outputs.orchestration_sha }}
        run: |
          set -euo pipefail
          intent_dir="${RUNNER_TEMP}/release-intent"
          build_dir="${RUNNER_TEMP}/release-build"
          state_dir="${RUNNER_TEMP}/callisto-release-state/${GITHUB_RUN_ID}"
          mkdir -p "$state_dir"
          args=(--source-root "$GITHUB_WORKSPACE/release-source" --intent "$intent_dir/release-intent.json" --state "$state_dir/execution-state.json" --receipt "$state_dir/release-receipt.json" --orchestration-revision "$ORCHESTRATION_SHA" --profile production)
          if [[ -n "$RELEASE_SOURCE_SHA_INPUT" ]]; then
            args+=(--recovery)
          fi
          if [[ -f "$build_dir/release-artifacts/manifest.json" ]]; then
            args+=(--artifact-manifest "$build_dir/release-artifacts/manifest.json" --artifact-dir "$build_dir/release-artifacts")
          fi
          callisto release execute "${args[@]}"

