404	fn observe_git_trust<R: CommandRunner, D: DependencyResolver>(
405	    workspace: &Workspace<'_, R, D>,
406	    trust_profile: ExecutionTrustProfileV1,
407	) -> Result<GitCommitTrustEvidence, GraphError> {
408	    if !matches!(trust_profile, ExecutionTrustProfileV1::GitCommit) {
409	        return Err(ReleaseIntentError::UnsupportedTrustProfile.into());
410	    }
411	    let evidence = workspace.git_access().observe_git_commit_trust()?;
412	    if evidence.canonical_root() != workspace.root {
413	        return Err(GraphError::ReleasePreconditionUnmet {
414	            requirement: ReleasePreconditionRequirement::CanonicalRootMatchesWorkspace,
415	        });
416	    }
417	    if evidence.head_disposition() != GitHeadDisposition::Detached {
418	        return Err(GraphError::ReleasePreconditionUnmet {
419	            requirement: ReleasePreconditionRequirement::DetachedHead,
420	        });
421	    }
422	    Ok(evidence)
423	}
