 28	use crate::error::CliError;
 29	use crate::output::write_json;
 30	use crate::runner::CliCommandRunner;
 31	use crate::workspace::{load_workspace, select_inference};
 32	
 33	pub fn handle(args: ReleaseArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
 34	    match args {
 35	        ReleaseArgs::Plan(args) => plan(args, global),
 36	        ReleaseArgs::Inspect(args) => inspect(args, global),
 37	        ReleaseArgs::Reconcile(args) => reconcile(args, global),
 38	        ReleaseArgs::ArtifactManifest(args) => artifact_manifest(args, global),
 39	        ReleaseArgs::Execute(args) => execute(args, global),
 40	    }
 41	}
 42	
 43	fn artifact_manifest(args: ReleaseArtifactManifestArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
 44	    if global.dry_run {
 45	        return Err(CliError::Other(
 46	            "release artifact-manifest needs an output file; remove --dry-run because it records build output"
 47	                .to_owned(),
 48	        ));
 49	    }
 50	    let intent = read_intent(&args.intent)?;
 51	    if intent.artifact_slots.is_empty() {
 52	        return Err(CliError::Other(
 53	            "release intent declares no binary artifact slots; no artifact manifest can be created".to_owned(),
 54	        ));
 55	    }
 56	    let root = args.artifact_dir.canonicalize().map_err(|source| CliError::Io {
 57	        source,
 58	        path: Some(args.artifact_dir.clone()),
 59	    })?;
 60	    if !matches!(intent.snapshot.source, callisto_model::SourceIdentity::GitCommit { .. }) {
 61	        return Err(CliError::Other(
 62	            "artifact manifests require a Git commit release source".to_owned(),
 63	        ));
 64	    }
 65	    let mut entries = Vec::with_capacity(intent.artifact_slots.len());
 66	    for slot in &intent.artifact_slots {
 67	        let path = root.join(&slot.asset_name);
 68	        let metadata = std::fs::symlink_metadata(&path).map_err(|source| CliError::Io {
 69	            source,
 70	            path: Some(path.clone()),
 71	        })?;
 72	        if metadata.file_type().is_symlink() || !metadata.is_file() {
 73	            return Err(CliError::Other(format!(
 74	                "artifact `{}` must be a regular file directly in `{}`",
 75	                slot.asset_name,
 76	                root.display()
 77	            )));
 78	        }
 79	        let canonical = path.canonicalize().map_err(|source| CliError::Io {
 80	            source,
 81	            path: Some(path.clone()),
 82	        })?;
 83	        if !canonical.starts_with(&root) {
 84	            return Err(CliError::Other(format!(
 85	                "artifact `{}` resolves outside `{}`",
 86	                slot.asset_name,
 87	                root.display()
 88	            )));
 89	        }
 90	        let file = std::fs::File::open(&canonical).map_err(|source| CliError::Io {
 91	            source,
 92	            path: Some(canonical.clone()),
 93	        })?;
 94	        let (digest, byte_length) = ArtifactDigest::from_reader(file).map_err(|source| CliError::Io {
 95	            source,
 96	            path: Some(canonical),
 97	        })?;
 98	        entries.push(ArtifactManifestEntryV1 {
 99	            slot: slot.clone(),
100	            digest: digest.clone(),
101	            byte_length,
102	            attestation: GitHubArtifactAttestationV1 {
103	                repository: slot.attestation_policy.repository.clone(),
104	                workflow_path: slot.attestation_policy.workflow_path.clone(),
105	                workflow_commit: slot.attestation_policy.workflow_commit.clone(),
106	                subject_digest: digest,
107	                source_commit: slot.attestation_policy.workflow_commit.clone(),
108	            },
109	        });
110	    }
111	    let manifest = ArtifactManifestV1::new(&intent, entries)
112	        .map_err(|error| CliError::Other(format!("cannot create artifact manifest: {error}")))?;
113	    let permit = ApplyPermit::granted_unless_dry_run(false).expect("non-dry-run permits writes");
114	    let content = serde_json::to_string_pretty(&manifest).expect("artifact manifest serializes") + "\n";
115	    callisto_model::atomic::atomic_write(&args.out, &content, &permit).map_err(|source| CliError::Io {
116	        source,
117	        path: Some(args.out.clone()),
118	    })?;
119	    match global.format {
120	        OutputFormat::Json => write_json(&mut std::io::stdout(), &manifest)?,
121	        OutputFormat::Text => println!("Artifact manifest saved to {}", args.out.display()),
122	    }
123	    Ok(ExitCode::SUCCESS)
124	}
125	
126	fn plan(args: ReleasePlanArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
127	    if global.dry_run {
128	        return Err(CliError::Other(
129	            "release plan needs an output file; remove --dry-run because planning is already read-only".to_string(),
130	        ));
131	    }
132	    let runner = CliCommandRunner;
133	    let profile = ReleaseProfileId::parse(&args.profile)
134	        .map_err(|error| CliError::Other(format!("invalid release profile `{}`: {error}", args.profile)))?;
135	    let source_global = source_global(global, args.source_root.as_deref());
136	    let workspace = load_workspace(&source_global, &runner)?;
137	    let decision = match args.from_release_commit.as_deref() {
138	        Some(raw) => {
139	            let commit = callisto_model::CommitSha::parse(raw)
140	                .map_err(|error| CliError::Other(format!("invalid merged release commit `{raw}`: {error}")))?;
141	            let decision_path = args
142	                .decision
143	                .as_deref()
144	                .expect("clap requires --decision alongside --from-release-commit");
145	            // The workflow intentionally passes an absolute decision path
146	            // from its separately checked-out release source. Git's commit
147	            // diff and `git show REV:path` both require a repository-relative
148	            // path, so normalize once at the CLI boundary rather than asking
149	            // graph code to infer a caller's checkout layout.
150	            let decision_path = if decision_path.is_absolute() {
151	                let decision_path = dunce::canonicalize(decision_path).map_err(|source| CliError::Io {
152	                    source,
153	                    path: Some(decision_path.to_path_buf()),
154	                })?;
155	                decision_path
156	                    .strip_prefix(&workspace.root)
157	                    .map_err(|_outside_source| {
158	                        CliError::Other(format!(
159	                            "release decision {} must be inside selected source root {}",
160	                            decision_path.display(),
161	                            workspace.root.display()
162	                        ))
163	                    })?
164	                    .to_path_buf()
165	            } else {
166	                decision_path.to_path_buf()
167	            };
168	            let decision_path = callisto_model::workspace_relative(&decision_path).map_err(|error| {
169	                CliError::Other(format!(
170	                    "invalid release decision path {}: {error}",
171	                    decision_path.display()
172	                ))
173	            })?;
174	            derive_release_commit_decision(&workspace, &commit, &decision_path)?
175	        }
176	        None => {
177	            let selections = args
178	                .packages
179	                .iter()
180	                .map(|raw| {
181	                    ReleasePackageId::parse(raw).map_err(|error| {
182	                        CliError::Other(format!(
183	                            "invalid release package `{raw}`: {error}; use an exact ecosystem-qualified identity such as cargo/callisto-cli"
184	                        ))
185	                    })
186	                })
187	                .collect::<Result<Vec<_>, _>>()?;
188	            let inference = select_inference();
189	            let version_plan =
190	                callisto_graph::commands::plan_version(&workspace, &inference, &VersionOptions::default())?;
191	            derive_selected_release_decision(&workspace, &version_plan, &selections)?
192	        }
193	    };
194	    let locator = IgnoreWalkLocator::new(&workspace.root);
195	    let intent = match (
196	        &workspace.config.product_release,
197	        &args.orchestration_revision,
198	        &args.artifact_repository,
199	    ) {
200	        (Some(_), Some(revision), Some(repository)) => {
201	            let workflow_commit = callisto_model::CommitSha::parse(revision)
202	                .map_err(|error| CliError::Other(format!("invalid orchestration revision `{revision}`: {error}")))?;
203	            let repository = callisto_model::GitHubRepository::parse(repository)
204	                .map_err(|error| CliError::Other(format!("invalid artifact repository `{repository}`: {error}")))?;
205	            let configured_profile = workspace
206	                .config
207	                .product_release
208	                .as_ref()
209	                .and_then(|release| release.profile(&profile))
210	                .ok_or_else(|| {
211	                    CliError::Other(format!(
212	                        "release profile `{}` is not configured with a forge destination",
213	                        profile.as_str()
214	                    ))
215	                })?;
216	            if configured_profile.forge_repository != repository {
217	                return Err(CliError::Other(format!(
218	                    "release profile `{}` targets forge repository `{}`, not `{}`",
219	                    profile.as_str(),
220	                    configured_profile.forge_repository.as_slug(),
221	                    repository.as_slug()
222	                )));
223	            }
224	            build_release_intent_with_artifacts(
225	                &workspace.root,
226	                &locator,
227	                &runner,
228	                &decision,
229	                profile.clone(),
230	                ExecutionTrustProfileV1::GitCommit,
231	                callisto_graph::commands::ArtifactBuildPolicy {
232	                    repository,
233	                    workflow_path: ".github/workflows/callisto-release.yml".to_owned(),
234	                    workflow_commit,
235	                },
236	            )?
237	        }
238	        (Some(_), _, _) => {
239	            return Err(CliError::Other(
240	                "product release planning requires --orchestration-revision and --artifact-repository".to_owned(),
241	            ));
242	        }
243	        (None, None, None) => build_release_intent(
244	            &workspace.root,
245	            &locator,
246	            &runner,
247	            &decision,
248	            profile,
249	            ExecutionTrustProfileV1::GitCommit,
250	        )?,
251	        (None, _, _) => {
252	            return Err(CliError::Other(
253	                "--orchestration-revision and --artifact-repository require a configured product release".to_owned(),
254	            ));
255	        }
256	    };
257	    let permit = ApplyPermit::granted_unless_dry_run(global.dry_run)
258	        .expect("release plan rejects --dry-run before creating its explicit output");
259	    write_intent(&args.out, &intent, &permit)?;
260	    match global.format {
261	        OutputFormat::Json => write_json(&mut std::io::stdout(), &intent)?,
262	        OutputFormat::Text => println!("Wrote release intent {} to {}", intent.digest(), args.out.display()),
263	    }
264	    Ok(ExitCode::SUCCESS)
265	}
266	
267	fn inspect(args: ReleaseInspectArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
268	    let value = read_json_file(&args.input)?;
269	    match global.format {
270	        OutputFormat::Json => write_json(&mut std::io::stdout(), &value)?,
271	        OutputFormat::Text => println!(
272	            "{}",
273	            serde_json::to_string_pretty(&value).expect("JSON value serializes")
274	        ),
275	    }
276	    Ok(ExitCode::SUCCESS)
277	}
278	
279	fn reconcile(args: ReleaseReconcileArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
280	    let intent = read_intent(&args.intent)?;
281	    let state = match args.state {
282	        Some(path) => ReleaseStateStore::new(path).load(&intent)?,
283	        None => None,
284	    }
285	    .unwrap_or_else(|| ReleaseExecutionStateV1::pending(&intent));
286	    let report = reconcile_release_execution(&intent, &state)?;
287	    match global.format {
288	        OutputFormat::Json => write_json(&mut std::io::stdout(), report.eligible())?,
289	        OutputFormat::Text => {
290	            for operation in report.eligible() {
291	                println!("eligible: {operation:?}");
292	            }
293	        }
294	    }
295	    Ok(ExitCode::SUCCESS)
296	}
297	
298	fn execute(args: ReleaseExecuteArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
299	    let intent = read_intent(&args.intent)?;
300	    let selected_profile = ReleaseProfileId::parse(&args.profile)
301	        .map_err(|error| CliError::Other(format!("invalid release profile `{}`: {error}", args.profile)))?;
302	    if selected_profile != intent.profile {
303	        return Err(CliError::Other(format!(
304	            "release execute profile `{}` does not match immutable intent profile `{}`",
305	            selected_profile.as_str(),
306	            intent.profile.as_str()
307	        )));
308	    }
309	    let manifest = args
310	        .artifact_manifest
311	        .as_deref()
312	        .map(read_artifact_manifest)
313	        .transpose()?;
314	    let verified_artifacts = match (
315	        intent.artifact_slots.is_empty(),
316	        manifest.as_ref(),
317	        args.artifact_dir.as_deref(),
318	    ) {
319	        (true, None, None) => None,
320	        (true, _, _) => {
321	            return Err(CliError::Other(
322	                "release intent declares no binary artifact slots; omit --artifact-manifest and --artifact-dir"
323	                    .to_owned(),
324	            ));
325	        }
326	        (false, Some(manifest), Some(directory)) => {
327	            let runner = CliCommandRunner;
328	            Some(verify_artifact_manifest(&intent, manifest, directory, &runner)?)
329	        }
330	        (false, _, _) => {
331	            return Err(CliError::Other(
332	                "release intent declares binary artifact slots; provide both --artifact-manifest and --artifact-dir"
333	                    .to_owned(),
334	            ));
335	        }
336	    };
337	    let runner = CliCommandRunner;
338	    let source_global = source_global(global, args.source_root.as_deref());
339	    let source_workspace = load_workspace(&source_global, &runner)?;
340	    if source_workspace.config.product_release.is_some() {
341	        let configured_profile = source_workspace
342	            .config
343	            .product_release
344	            .as_ref()
345	            .and_then(|release| release.profile(&selected_profile))
346	            .ok_or_else(|| {
347	                CliError::Other(format!(
348	                    "release profile `{}` is not configured with a forge destination",
349	                    selected_profile.as_str()
350	                ))
351	            })?;
352	        if intent
353	            .artifact_slots
354	            .iter()
355	            .any(|slot| slot.attestation_policy.repository != configured_profile.forge_repository)
356	        {
357	            return Err(CliError::Other(format!(
358	                "release intent artifact destination does not match profile `{}` forge repository `{}`",
359	                selected_profile.as_str(),
360	                configured_profile.forge_repository.as_slug()
361	            )));
362	        }
363	    }
364	    let root = dunce::canonicalize(&source_global.cwd).map_err(|source| CliError::Io {
365	        source,
366	        path: Some(source_global.cwd.clone()),
367	    })?;
368	    let locator = IgnoreWalkLocator::new(&root);
369	    let explicit_state_directory = args.state.as_deref().and_then(std::path::Path::parent);
370	    let capability =
371	        validate_release_intent_with_state_directory(&root, &locator, &runner, explicit_state_directory, intent)?;
372	    let store = match args.state {
373	        Some(path) => ReleaseStateStore::new(path),
374	        None => ReleaseStateStore::default_for(&root, capability.intent())?,
375	    };
376	    let permit = ApplyPermit::granted_unless_dry_run(global.dry_run).ok_or_else(|| {
377	        CliError::Other(
378	            "release execute cannot run with --dry-run; use release reconcile for a read-only readiness check"
379	                .to_string(),
380	        )
381	    })?;
382	    let state = execute_release_with_artifacts_in_recovery(
383	        &capability,
384	        &store,
385	        &permit,
386	        verified_artifacts.as_ref(),
387	        args.recovery,
388	    )?;
389	    let orchestration_revision = callisto_model::CommitSha::parse(&args.orchestration_revision).map_err(|error| {
390	        CliError::Other(format!(
391	            "invalid orchestration revision `{}`: {error}",
392	            args.orchestration_revision
393	        ))
394	    })?;
395	    let source = match &capability.intent().snapshot.source {
396	        callisto_model::SourceIdentity::GitCommit { sha } => sha.clone(),
397	        callisto_model::SourceIdentity::HermeticContent { .. } => {
398	            return Err(CliError::Other(
399	                "release receipts require a Git commit release source".to_owned(),
400	            ))
401	        }
402	    };
403	    let mut provenance = ReleaseRunProvenanceV1::new(
404	        if args.recovery {
405	            ReleaseRunKindV1::Recovery
406	        } else {
407	            ReleaseRunKindV1::Initial
408	        },
409	        orchestration_revision,
410	        source,
411	        selected_profile,
412	        capability.intent().digest().clone(),
413	    );
414	    if let Some(artifacts) = verified_artifacts.as_ref() {
415	        provenance = provenance.with_artifact_manifest_digest(artifacts.manifest().digest());
416	    }
417	    let receipt = ReleaseReceiptV1::from_evidence(
418	        capability.intent(),
419	        &state,
420	        provenance,
421	        observe_release_operations_with_artifacts(&capability, verified_artifacts.as_ref())?,
422	    )
423	    .map_err(|error| CliError::Other(format!("cannot issue terminal release receipt: {error}")))?;
424	    write_receipt(&args.receipt, &receipt, &permit)?;
425	    match global.format {
426	        OutputFormat::Json => write_json(&mut std::io::stdout(), &receipt)?,
427	        OutputFormat::Text => println!(
428	            "Release receipt saved to {} (execution state: {})",
429	            args.receipt.display(),
430	            store.path().display()
431	        ),
432	    }
433	    Ok(ExitCode::SUCCESS)
434	}
435	
436	fn source_global(global: &GlobalArgs, source_root: Option<&std::path::Path>) -> GlobalArgs {
437	    let mut source = global.clone();
438	    if let Some(root) = source_root {
439	        source.cwd = root.to_path_buf();
440	    }
441	    source
442	}
443	
444	fn read_intent(path: &std::path::Path) -> Result<ReleaseIntentV1, CliError> {
445	    serde_json::from_value(read_json_file(path)?)
446	        .map_err(|error| CliError::Other(format!("invalid release intent {}: {error}", path.display())))
447	}
448	
449	fn read_artifact_manifest(path: &std::path::Path) -> Result<ArtifactManifestV1, CliError> {
450	    serde_json::from_value(read_json_file(path)?)
451	        .map_err(|error| CliError::Other(format!("invalid artifact manifest {}: {error}", path.display())))
452	}
453	
454	fn read_json_file(path: &std::path::Path) -> Result<serde_json::Value, CliError> {
455	    let content = std::fs::read_to_string(path).map_err(|source| CliError::Io {
456	        source,
457	        path: Some(path.to_path_buf()),
458	    })?;
459	    serde_json::from_str(&content)
460	        .map_err(|error| CliError::Other(format!("invalid JSON in {}: {error}", path.display())))
461	}
462	
463	fn write_intent(path: &std::path::Path, intent: &ReleaseIntentV1, permit: &ApplyPermit) -> Result<(), CliError> {
464	    let content = serde_json::to_string_pretty(intent).expect("release intent serializes") + "\n";
465	    callisto_model::atomic::atomic_write(path, &content, permit).map_err(|source| CliError::Io {
466	        source,
467	        path: Some(path.to_path_buf()),
468	    })?;
469	    Ok(())
470	}
471	
472	fn write_receipt(path: &std::path::Path, receipt: &ReleaseReceiptV1, permit: &ApplyPermit) -> Result<(), CliError> {
473	    let content = serde_json::to_string_pretty(receipt).expect("release receipt serializes") + "\n";
474	    callisto_model::atomic::atomic_write(path, &content, permit).map_err(|source| CliError::Io {
475	        source,
476	        path: Some(path.to_path_buf()),
477	    })
478	}

