  1	//! Artifact-byte and GitHub-attestation verification for durable releases.
  2	//!
  3	//! A manifest is only a claim. This module verifies the actual on-disk bytes
  4	//! and asks GitHub to validate the signing certificate against the policy
  5	//! embedded in the immutable release intent before an executor can upload an
  6	//! asset. It intentionally owns no upload side effect.
  7	
  8	use std::{
  9	    fs::{self, File},
 10	    path::{Component, Path, PathBuf},
 11	    time::Duration,
 12	};
 13	
 14	use callisto_model::{ArtifactManifestV1, CommandRunner, ReleaseIntentV1};
 15	
 16	use crate::GraphError;
 17	
 18	const ATTESTATION_TIMEOUT: Duration = Duration::from_secs(120);
 19	
 20	/// A manifest whose exact local bytes and GitHub provenance have been checked.
 21	///
 22	/// The constructor is private: callers can obtain this capability only with
 23	/// [`verify_artifact_manifest`]. It borrows the manifest so an executor cannot
 24	/// silently substitute a different manifest after verification.
 25	#[derive(Debug)]
 26	pub struct VerifiedArtifactManifest<'a> {
 27	    manifest: &'a ArtifactManifestV1,
 28	    root: PathBuf,
 29	}
 30	
 31	impl<'a> VerifiedArtifactManifest<'a> {
 32	    pub fn manifest(&self) -> &'a ArtifactManifestV1 {
 33	        self.manifest
 34	    }
 35	
 36	    pub(crate) fn path_for(&self, slot: &callisto_model::ArtifactSlotId) -> Result<PathBuf, GraphError> {
 37	        resolve_asset_path(&self.root, &slot.asset_name)
 38	    }
 39	
 40	    /// Returns the already intent-bound manifest entry for `slot`.
 41	    pub(crate) fn entry_for(
 42	        &self,
 43	        slot: &callisto_model::ArtifactSlotId,
 44	    ) -> Result<&callisto_model::ArtifactManifestEntryV1, GraphError> {
 45	        self.manifest
 46	            .entries
 47	            .iter()
 48	            .find(|entry| entry.slot == *slot)
 49	            .ok_or_else(|| GraphError::ReleaseInvariant {
 50	                detail: format!("verified artifact manifest has no entry for `{}`", slot.asset_name),
 51	            })
 52	    }
 53	}
 54	
 55	/// Verifies every manifest entry against the exact artifact directory.
 56	///
 57	/// The artifact directory and every candidate are canonicalized, and symbolic
 58	/// links are rejected, so a manifest asset name cannot escape the supplied
 59	/// build-output directory. Each asset is streamed once for a bounded-memory
 60	/// SHA-256 and size comparison. `gh attestation verify` then validates the
 61	/// repository, workflow path and commit, source commit, and hosted-runner
 62	/// policy declared by the immutable artifact slot.
 63	pub fn verify_artifact_manifest<'a, R: CommandRunner>(
 64	    intent: &ReleaseIntentV1,
 65	    manifest: &'a ArtifactManifestV1,
 66	    artifact_root: &Path,
 67	    runner: &R,
 68	) -> Result<VerifiedArtifactManifest<'a>, GraphError> {
 69	    manifest
 70	        .validate_for_intent(intent)
 71	        .map_err(|source| GraphError::ArtifactManifest { source })?;
 72	
 73	    let root = canonical_artifact_root(artifact_root)?;
 74	    for entry in &manifest.entries {
 75	        let path = resolve_asset_path(&root, &entry.slot.asset_name)?;
 76	        let file = File::open(&path).map_err(|error| GraphError::ArtifactRead {
 77	            path: path.clone(),
 78	            message: error.to_string(),
 79	        })?;
 80	        let (digest, length) =
 81	            callisto_model::ArtifactDigest::from_reader(file).map_err(|error| GraphError::ArtifactRead {
 82	                path: path.clone(),
 83	                message: error.to_string(),
 84	            })?;
 85	        if digest != entry.digest || length != entry.byte_length {
 86	            return Err(GraphError::ArtifactBytesMismatch { path });
 87	        }
 88	
 89	        verify_github_attestation(&path, entry, runner)?;
 90	    }
 91	    Ok(VerifiedArtifactManifest { manifest, root })
 92	}
 93	
 94	fn canonical_artifact_root(artifact_root: &Path) -> Result<PathBuf, GraphError> {
 95	    let metadata = fs::metadata(artifact_root).map_err(|error| GraphError::ArtifactRead {
 96	        path: artifact_root.to_path_buf(),
 97	        message: error.to_string(),
 98	    })?;
 99	    if !metadata.is_dir() {
100	        return Err(GraphError::UnsafeArtifactPath {
101	            path: artifact_root.to_path_buf(),
102	            reason: "artifact root is not a directory",
103	        });
104	    }
105	    artifact_root.canonicalize().map_err(|error| GraphError::ArtifactRead {
106	        path: artifact_root.to_path_buf(),
107	        message: error.to_string(),
108	    })
109	}
110	
111	fn resolve_asset_path(root: &Path, asset_name: &str) -> Result<PathBuf, GraphError> {
112	    let relative = Path::new(asset_name);
