 75	        let path = resolve_asset_path(&root, &entry.slot.asset_name)?;
 76	        let file = File::open(&path).map_err(|error| GraphError::ArtifactRead {
 77	            path: path.clone(),
 78	            message: error.to_string(),
 79	        })?;
 80	        let (digest, length) =
 81	            callisto_model::ArtifactDigest::from_reader(file).map_err(|error| GraphError::ArtifactRead {
 82	                path: path.clone(),
 83	                message: error.to_string(),
 84	            })?;
 85	        if digest != entry.digest || length != entry.byte_length {
 86	            return Err(GraphError::ArtifactBytesMismatch { path });
 87	        }
 88	
 89	        verify_github_attestation(&path, entry, runner)?;
 90	    }
 91	    Ok(VerifiedArtifactManifest { manifest, root })
 92	}
