1339	impl<'de> Deserialize<'de> for ReleaseIntentV1 {
1340	    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
1341	    where
1342	        D: Deserializer<'de>,
1343	    {
1344	        let wire = ReleaseIntentV1Wire::deserialize(deserializer)?;
1345	        check_schema_version::<D::Error>(wire.schema_version, Self::SCHEMA_VERSION, "release intent")?;
1346	        check_schema_version::<D::Error>(
1347	            wire.decision.schema_version,
1348	            ReleaseDecisionV1::SCHEMA_VERSION,
1349	            "release intent",
1350	        )?;
1351	        check_schema_version::<D::Error>(
1352	            wire.snapshot.schema_version,
1353	            ReleaseInputSnapshotV1::SCHEMA_VERSION,
1354	            "release intent",
1355	        )?;
1356	        if wire.snapshot.packages.windows(2).any(|pair| pair[0] >= pair[1]) {
1357	            return Err(serde::de::Error::custom("release input packages are not canonical"));
1358	        }
1359	        let intent = Self::new(
1360	            wire.profile,
1361	            wire.decision,
1362	            wire.snapshot,
1363	            wire.trust_profile,
1364	            wire.operations,
1365	            wire.artifact_slots,
1366	        )
1367	        .map_err(serde::de::Error::custom)?;
1368	        if intent.digest != wire.digest {
1369	            return Err(serde::de::Error::custom(
1370	                "release intent digest does not match canonical content",
1371	            ));
1372	        }
1373	        Ok(intent)
1374	    }
1375	}
