1377	impl ReleaseIntentV1 {
1378	    pub const SCHEMA_VERSION: u8 = 2;
1379	
1380	    pub fn new(
1381	        profile: ReleaseProfileId,
1382	        decision: ReleaseDecisionV1,
1383	        snapshot: ReleaseInputSnapshotV1,
1384	        trust_profile: ExecutionTrustProfileV1,
1385	        operations: Vec<ReleaseOperation>,
1386	        mut artifact_slots: Vec<ArtifactSlotId>,
1387	    ) -> Result<Self, ReleaseIntentError> {
1388	        if !matches!(trust_profile, ExecutionTrustProfileV1::GitCommit)
1389	            || !matches!(snapshot.source, SourceIdentity::GitCommit { .. })
1390	        {
1391	            return Err(ReleaseIntentError::UnsupportedTrustProfile);
1392	        }
1393	        validate_operations(&operations)?;
1394	        validate_operation_roster(&decision, &operations)?;
1395	        artifact_slots.sort();
1396	        if artifact_slots.windows(2).any(|pair| pair[0] == pair[1]) {
1397	            return Err(ReleaseIntentError::DuplicateArtifactSlot);
1398	        }
1399	        if artifact_slots.iter().any(|slot| {
1400	            !decision
1401	                .entries
1402	                .iter()
1403	                .any(|entry| entry.package == slot.package && entry.target_version == slot.version)
1404	        }) {
1405	            return Err(ReleaseIntentError::ArtifactSlotOutsideDecision);
1406	        }
