1411	            &snapshot,
1412	            trust_profile,
1413	            &operations,
1414	            &artifact_slots,
1415	        );
1416	        Ok(Self {
1417	            schema_version: Self::SCHEMA_VERSION,
1418	            profile,
1419	            decision,
1420	            snapshot,
1421	            trust_profile,
1422	            operations,
1423	            artifact_slots,
1424	            digest,
1425	        })
1426	    }
