1477	fn validate_operation_roster(
1478	    decision: &ReleaseDecisionV1,
1479	    operations: &[ReleaseOperation],
1480	) -> Result<(), ReleaseIntentError> {
1481	    let roster = &decision.entries;
1482	    for operation in operations {
