1495	fn validate_artifact_upload_roster(
1496	    operations: &[ReleaseOperation],
1497	    artifact_slots: &[ArtifactSlotId],
1498	) -> Result<(), ReleaseIntentError> {
1499	    let mut uploads = operations
1500	        .iter()
