294	/// Builds an intent whose declared binary slots are bound to the current
295	/// coordinator workflow. Callers recovering an old release source must pass
296	/// the current coordinator revision here, never substitute the source SHA.
297	pub fn build_release_intent_with_artifacts<L: ProjectLocator, R: CommandRunner>(
298	    root: &Path,
299	    locator: &L,
300	    runner: &R,
301	    decision: &ReleaseDecisionV1,
302	    profile: ReleaseProfileId,
303	    trust_profile: ExecutionTrustProfileV1,
304	    artifact_policy: ArtifactBuildPolicy,
305	) -> Result<ReleaseIntentV1, GraphError> {
306	    let root = canonical_root(root)?;
307	    let workspace = Workspace::load(root.clone(), locator, runner)?;
308	    let source = observe_source(&workspace, trust_profile)?;
309	    let intent = derive_release_intent(
310	        &workspace,
311	        decision,
312	        profile,
313	        source.clone(),
314	        trust_profile,
315	        Some(&artifact_policy),
316	    )?;
317	    if observe_source(&workspace, trust_profile)? != source {
318	        return Err(GraphError::ReleaseIntentStale {
319	            reason: StaleReason::source_identity_changed(),
320	        });
321	    }
322	    Ok(intent)
323	}
