1049	        let reference = format!("refs/tags/{name}^{{commit}}");
1050	        let rev_parse_args = ["rev-parse", "--verify", "--quiet", reference.as_str()];
1051	        let observed = self.runner.run("git", &rev_parse_args, &self.prepared.root)?;
1052	        if observed.exit_code != Some(0) {
1053	            return Ok(None);
1054	        }
1055	        let target = CommitSha::parse(observed.stdout.trim()).map_err(|error| GraphError::ReleaseCommand {
1056	            program: "git".to_string(),
1057	            args: rev_parse_args.iter().map(ToString::to_string).collect(),
1058	            failure: CommandFailure::MalformedOutput {
1059	                detail: error.to_string(),
1060	            },
1061	        })?;
1062	        let for_each_ref_target = format!("refs/tags/{name}");
1063	        let for_each_ref_args = [
1064	            "for-each-ref",
1065	            "--format=%(objecttype)%00%(contents:subject)%00%(contents:body)",
1066	            for_each_ref_target.as_str(),
1067	        ];
1068	        let details = self.runner.run("git", &for_each_ref_args, &self.prepared.root)?;
1069	        if details.exit_code != Some(0) {
1070	            return Err(GraphError::ReleaseCommand {
1071	                program: "git".to_string(),
1072	                args: for_each_ref_args.iter().map(ToString::to_string).collect(),
1073	                failure: CommandFailure::NonZeroExit {
1074	                    exit_code: details.exit_code,
1075	                    stderr: details.stderr,
1076	                },
1077	            });
1078	        }
1079	        let line = details.stdout.trim_end_matches(['\r', '\n']);
1080	        let mut fields = line.split('\0');
1081	        let object_type = fields.next();
1082	        let annotation = fields.next();
1083	        let body = fields.next();
1084	        if object_type != Some("tag") || body.is_none_or(|body| !body.trim().is_empty()) || fields.next().is_some() {
1085	            return Err(GraphError::ReleaseCommand {
1086	                program: "git".to_string(),
1087	                args: for_each_ref_args.iter().map(ToString::to_string).collect(),
1088	                failure: CommandFailure::MalformedOutput {
1089	                    detail: format!("unexpected for-each-ref output: {line:?}"),
1090	                },
1091	            });
1092	        }
1093	        let annotation = annotation.ok_or_else(|| GraphError::ReleaseInvariant {
1094	            detail: "for-each-ref line validated as `tag`/empty-body but carried no annotation field".to_string(),
1095	        })?;
