270	/// Builds a release intent from a fresh root-bound observation.
271	pub fn build_release_intent<L: ProjectLocator, R: CommandRunner>(
272	    root: &Path,
273	    locator: &L,
274	    runner: &R,
275	    decision: &ReleaseDecisionV1,
276	    profile: ReleaseProfileId,
277	    trust_profile: ExecutionTrustProfileV1,
278	) -> Result<ReleaseIntentV1, GraphError> {
279	    let root = canonical_root(root)?;
280	    let workspace = Workspace::load(root.clone(), locator, runner)?;
281	    let source = observe_source(&workspace, trust_profile)?;
282	    let intent = derive_release_intent(&workspace, decision, profile, source.clone(), trust_profile, None)?;
283	
284	    // Recheck after all input reads. A concurrent edit or checkout cannot be
285	    // authorized merely because it happened after the first check.
286	    if observe_source(&workspace, trust_profile)? != source {
287	        return Err(GraphError::ReleaseIntentStale {
288	            reason: StaleReason::source_identity_changed(),
289	        });
290	    }
291	    Ok(intent)
292	}
