326	/// the exact operation DAG before creating an opaque authorization capability.
327	pub fn validate_release_intent<'a, L: ProjectLocator, R: CommandRunner>(
328	    root: &Path,
329	    locator: &L,
330	    runner: &'a R,
331	    received: ReleaseIntentV1,
