336	/// Validates an intent while placing its workspace lock under an explicit
337	/// caller-owned state directory.
338	///
339	/// CI callers that supply an explicit durable state file must use its parent
340	/// here as well.  Otherwise validation would still depend on the runner's
341	/// implicit platform state location, defeating hermetic job handoff.
342	pub fn validate_release_intent_with_state_directory<'a, L: ProjectLocator, R: CommandRunner>(
343	    root: &Path,
344	    locator: &L,
345	    runner: &'a R,
346	    state_directory: Option<&Path>,
347	    received: ReleaseIntentV1,
348	) -> Result<ValidatedReleaseIntent<'a>, GraphError> {
349	    let root = canonical_root(root)?;
350	    let workspace = Workspace::load(root.clone(), locator, runner)?;
351	    let initial_trust = observe_git_trust(&workspace, received.trust_profile)?;
352	    let lock = ReleaseWorkspaceLock::acquire(&root, state_directory)?;
353	    let trust = observe_git_trust(&workspace, received.trust_profile)?;
354	    if trust != initial_trust {
355	        return Err(GraphError::ReleaseIntentStale {
356	            reason: StaleReason::trust_evidence_changed(),
357	        });
358	    }
359	    let source = source_from_trust(&trust);
360	    let artifact_policy = artifact_policy_from_intent(&received)?;
361	    let (expected, prepared) = derive_release_intent_with_prepared(
362	        &workspace,
363	        &received.decision,
364	        received.profile.clone(),
365	        source.clone(),
366	        received.trust_profile,
367	        artifact_policy.as_ref(),
368	    )?;
369	    let final_trust = observe_git_trust(&workspace, received.trust_profile)?;
370	    if expected != received || final_trust != trust {
371	        return Err(GraphError::ReleaseIntentStale {
372	            reason: StaleReason::intent_differs_from_fresh_derivation(),
373	        });
374	    }
375	
376	    Ok(ValidatedReleaseIntent {
377	        prepared: PreparedReleaseInputs {
378	            root,
379	            source,
380	            trust: final_trust,
381	            git_remote: prepared.git_remote,
382	            _lock: lock,
383	            operations: prepared.operations,
384	        },
385	        intent: received,
386	        runner,
387	    })
388	}
