1171	fn parse_github_api_response<'a>(program: &str, args: &[&str], stdout: &'a str) -> Result<(u16, &'a str), GraphError> {
1172	    let malformed = |detail: String| GraphError::ReleaseCommand {
1173	        program: program.to_string(),
1174	        args: args.iter().map(ToString::to_string).collect(),
1175	        failure: CommandFailure::MalformedOutput { detail },
1176	    };
1177	    let (headers, body) = stdout
1178	        .rsplit_once("\r\n\r\n")
1179	        .or_else(|| stdout.rsplit_once("\n\n"))
1180	        .ok_or_else(|| malformed("response has no blank line separating headers from body".to_string()))?;
1181	    let status_line = headers
1182	        .lines()
1183	        .rev()
1184	        .find(|line| line.trim_end_matches('\r').starts_with("HTTP/"))
1185	        .ok_or_else(|| malformed("response headers contain no HTTP status line".to_string()))?;
1186	    let status = status_line
1187	        .split_whitespace()
1188	        .nth(1)
1189	        .ok_or_else(|| malformed(format!("HTTP status line has no status code: {status_line:?}")))?
1190	        .parse::<u16>()
1191	        .map_err(|error| malformed(format!("HTTP status code is not a valid number: {error}")))?;
1192	    Ok((status, body))
1193	}
