1433	fn digest_intent(
1434	    profile: &ReleaseProfileId,
1435	    decision: &ReleaseDecisionV1,
1436	    snapshot: &ReleaseInputSnapshotV1,
1437	    trust_profile: ExecutionTrustProfileV1,
1438	    operations: &[ReleaseOperation],
1439	    artifact_slots: &[ArtifactSlotId],
1440	) -> IntentDigest {
1441	    let mut transcript = CanonicalTranscript::intent_v1();
1442	    transcript.push_bytes("schema", [ReleaseIntentV1::SCHEMA_VERSION]);
1443	    transcript.push_str("profile", profile.as_str());
1444	    transcript.push_str("decision", decision.digest.as_str());
1445	    transcript.push_str("snapshot", snapshot.digest().as_str());
1446	    transcript.push_str(
1447	        "trust-profile",
1448	        match trust_profile {
1449	            ExecutionTrustProfileV1::GitCommit => "git-commit",
1450	            ExecutionTrustProfileV1::HermeticContent => "hermetic-content",
1451	        },
1452	    );
1453	    for operation in operations {
1454	        transcript.push_str("operation", &operation_id_text(&operation.id));
1455	        for prerequisite in &operation.prerequisites {
1456	            transcript.push_str("prerequisite", &operation_id_text(prerequisite));
1457	        }
1458	    }
1459	    for slot in artifact_slots {
1460	        transcript.push_str("artifact-slot.package", &slot.package.to_string());
1461	        transcript.push_str("artifact-slot.version", slot.version.render());
1462	        transcript.push_str("artifact-slot.platform", &slot.platform);
1463	        transcript.push_str("artifact-slot.asset", &slot.asset_name);
1464	        transcript.push_str(
1465	            "artifact-slot.repository",
1466	            &slot.attestation_policy.repository.as_slug(),
1467	        );
1468	        transcript.push_str("artifact-slot.workflow-path", &slot.attestation_policy.workflow_path);
1469	        transcript.push_str(
1470	            "artifact-slot.workflow-commit",
1471	            slot.attestation_policy.workflow_commit.as_str(),
1472	        );
1473	    }
