  1658	fn canonical_operation_order(
  1659	    operations: BTreeMap<ReleaseOperationId, ReleaseOperation>,
  1660	) -> Result<Vec<ReleaseOperation>, GraphError> {
  1661	    let mut remaining: BTreeMap<_, usize> = operations
  1662	        .iter()
  1663	        .map(|(id, operation)| (id.clone(), operation.prerequisites().len()))
  1664	        .collect();
  1665	    let mut dependents = BTreeMap::<ReleaseOperationId, Vec<ReleaseOperationId>>::new();
  1666	    for (id, operation) in &operations {
  1667	        for prerequisite in operation.prerequisites() {
  1668	            dependents.entry(prerequisite.clone()).or_default().push(id.clone());
  1669	        }
  1670	    }
  1671	    let mut ready: BTreeSet<_> = remaining
  1672	        .iter()
  1673	        .filter_map(|(id, count)| (*count == 0).then_some(id.clone()))
  1674	        .collect();
  1675	    let mut ordered = Vec::with_capacity(operations.len());
  1676	    while let Some(id) = ready.pop_first() {
  1677	        ordered.push(operations.get(&id).expect("known operation").clone());
  1678	        for dependent in dependents.get(&id).into_iter().flatten() {
  1679	            let count = remaining.get_mut(dependent).expect("known operation");
  1680	            *count -= 1;
  1681	            if *count == 0 {
  1682	                ready.insert(dependent.clone());
  1683	            }
  1684	        }
  1685	    }
  1686	    if ordered.len() != operations.len() {
  1687	        return Err(GraphError::ReleaseInvariant {
  1688	            detail: "release operation DAG contains a cycle: topological sort could not order every operation"
  1689	                .to_string(),
  1690	        });
  1691	    }
  1692	    Ok(ordered)
  1693	}
