1890	fn canonical_registry_binding(registry: &str, raw: &str) -> Result<RegistryBindingV1, GraphError> {
1891	    let parsed = url::Url::parse(raw).map_err(|error| GraphError::UnsafeRegistryBinding {
1892	        registry: registry.to_string(),
1893	        reason: url_parse_error_reason(error),
1894	    })?;
1895	    if parsed.cannot_be_a_base() || parsed.host_str().is_none() {
1896	        return Err(GraphError::UnsafeRegistryBinding {
1897	            registry: registry.to_string(),
1898	            reason: "URL must have an authority",
1899	        });
1900	    }
1901	    if !matches!(parsed.scheme(), "http" | "https") {
1902	        return Err(GraphError::UnsafeRegistryBinding {
1903	            registry: registry.to_string(),
1904	            reason: "URL scheme must be http or https",
1905	        });
1906	    }
1907	    if !parsed.username().is_empty() || parsed.password().is_some() {
1908	        return Err(GraphError::UnsafeRegistryBinding {
1909	            registry: registry.to_string(),
1910	            reason: "userinfo is forbidden",
1911	        });
1912	    }
1913	    if parsed.query().is_some() {
1914	        return Err(GraphError::UnsafeRegistryBinding {
1915	            registry: registry.to_string(),
1916	            reason: "query string is forbidden",
1917	        });
1918	    }
1919	    if parsed.fragment().is_some() {
1920	        return Err(GraphError::UnsafeRegistryBinding {
1921	            registry: registry.to_string(),
1922	            reason: "fragment is forbidden",
1923	        });
1924	    }
1925	    Ok(RegistryBindingV1 {
1926	        scheme: parsed.scheme().to_ascii_lowercase(),
1927	        host: parsed.host_str().expect("validated authority").to_ascii_lowercase(),
1928	        effective_port: parsed.port_or_known_default(),
1929	        path: parsed.path().to_string(),
1930	    })
1931	}
