 153	fn resolve_product_release(raw: RawProductReleaseConfig) -> Result<ProductReleaseConfig, ConfigError> {
 154	    let package = PackageId::parse(&raw.product_package).map_err(|_error| ConfigError::InvalidProductRelease {
 155	        detail: "product-package must be an ecosystem-qualified package identity".to_owned(),
 156	    })?;
 157	    const TARGETS: [&str; 4] = [
 158	        "aarch64-apple-darwin",
 159	        "x86_64-unknown-linux-gnu",
 160	        "x86_64-unknown-linux-musl",
 161	        "wasm32-wasip1",
 162	    ];
 163	    if raw.artifact_targets.len() != TARGETS.len()
 164	        || raw
 165	            .artifact_targets
 166	            .iter()
 167	            .any(|target| !TARGETS.contains(&target.as_str()))
 168	        || raw.artifact_targets.iter().collect::<BTreeSet<_>>().len() != TARGETS.len()
 169	    {
 170	        return Err(ConfigError::InvalidProductRelease {
 171	            detail: "artifact-targets must contain each supported product target exactly once".to_owned(),
 172	        });
 173	    }
 174	    let profiles = raw
 175	        .profiles
 176	        .unwrap_or_default()
 177	        .into_iter()
 178	        .map(|(name, raw)| resolve_release_profile(name, raw))
 179	        .collect::<Result<BTreeMap<_, _>, _>>()?;
 180	    for (profile, destination) in &profiles {
 181	        if let Some((other, _)) = profiles
 182	            .iter()
 183	            .find(|(other, candidate)| *other != profile && candidate.forge_repository == destination.forge_repository)
 184	        {
 185	            return Err(ConfigError::InvalidProductRelease {
 186	                detail: format!(
 187	                    "release profiles `{}` and `{}` share forge-repository `{}`",
 188	                    profile.as_str(),
 189	                    other.as_str(),
 190	                    destination.forge_repository.as_slug()
 191	                ),
 192	            });
 193	        }
 194	    }
 195	    Ok(ProductReleaseConfig {
 196	        package,
 197	        artifact_targets: TARGETS.iter().map(|target| (*target).to_owned()).collect(),
 198	        profiles,
 199	    })
 200	}
