 202	fn resolve_release_profile(
 203	    name: String,
 204	    raw: RawReleaseProfileConfig,
 205	) -> Result<(ReleaseProfileId, ReleaseProfileConfig), ConfigError> {
 206	    let profile = ReleaseProfileId::parse(&name).map_err(|error| ConfigError::InvalidProductRelease {
 207	        detail: format!("release profile `{name}` is invalid: {error}"),
 208	    })?;
 209	    let forge_repository =
 210	        GitHubRepository::parse(&raw.forge_repository).map_err(|error| ConfigError::InvalidProductRelease {
 211	            detail: format!("release profile `{name}` has invalid forge-repository: {error}"),
 212	        })?;
 213	    let registry_routes = raw
 214	        .registry_routes
 215	        .unwrap_or_default()
 216	        .into_iter()
 217	        .map(|(logical, destination)| (RegistryKey(logical), RegistryKey(destination)))
 218	        .collect();
 219	    Ok((
 220	        profile,
 221	        ReleaseProfileConfig {
 222	            forge_repository,
 223	            registry_routes,
 224	        },
 225	    ))
 226	}
