 171	            detail: "artifact-targets must contain each supported product target exactly once".to_owned(),
 172	        });
 173	    }
 174	    let profiles = raw
 175	        .profiles
 176	        .unwrap_or_default()
 177	        .into_iter()
 178	        .map(|(name, raw)| resolve_release_profile(name, raw))
 179	        .collect::<Result<BTreeMap<_, _>, _>>()?;
 180	    for (profile, destination) in &profiles {
