  1931	    /// Validates that this state belongs to this exact intent and operation roster.
  1932	    ///
  1933	    /// Resume and reconciliation must call this before treating any state as
  1934	    /// evidence or before making a remote/VCS mutation.
  1935	    pub fn validate_for_intent(&self, intent: &ReleaseIntentV1) -> Result<(), ReleaseStateError> {
  1936	        if self.schema_version != Self::SCHEMA_VERSION {
  1937	            return Err(ReleaseStateError::UnsupportedSchema {
